#include <stdio.h>



int main(void)
{
    int start[]={1,3,5,8},finish[]={4,5,7,9},count=0,last=0;
    for(int i=0;i<4;i++){
        if(count==0||start[i]>=last){count++;last=finish[i];}
    }
    printf("%d\n",count);
    return 0;
}

